package ru.fragment.logoeditor;
import android.content.*;
import android.content.pm.*;
import android.os.Build;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;
/** Single-flight foreground updater. Only installation is deferred; downloads never are. */
public final class UpdateManager {
 public interface Host {void state(JSONObject value);void install(File file);}
 private final Context context;private final Host host;private final SharedPreferences prefs;private final File dir;
 private boolean busy=false,pending=false,manual=false,installActive=false;private long epoch=0;private Spec ready;
 private JSONObject state=new JSONObject();
 private static final String FEED="https://raw.githubusercontent.com/nicolenkoe/fragment-logo-editor/gh-pages/versions.json";
 private static final class Cancelled extends IOException {}
 private static final class Spec {UpdatePolicy.Release release;long size;String sha;Set<String> signers;File file;}
 public UpdateManager(Context c,Host h){context=c.getApplicationContext();host=h;prefs=context.getSharedPreferences("fragment-updates-v2",0);dir=new File(context.getFilesDir(),"updates");dir.mkdirs();}
 public synchronized String settings(){try{return new JSONObject().put("stableOnly",stableOnly()).put("version",installed().versionName).put("versionCode",installed().versionCode).toString();}catch(Exception e){return "{}";}}
 public synchronized String snapshot(){return state.toString();}
 public boolean stableOnly(){return prefs.getBoolean("stableOnly",false);}
 public synchronized void setStableOnly(boolean value){if(stableOnly()==value){check(true);return;}prefs.edit().putBoolean("stableOnly",value).apply();epoch++;ready=null;if(busy){pending=true;manual=true;}else check(true);}
 public synchronized void check(boolean requested){manual|=requested;if(busy)return;busy=true;final long generation=epoch;new Thread(new Runnable(){public void run(){try{perform(generation);}catch(Cancelled ignored){}catch(Exception error){emit(generation,"error",error.getMessage()==null?"Не удалось проверить или скачать обновление. Проверьте интернет.":error.getMessage(),null);}finally{boolean again; synchronized(UpdateManager.this){busy=false;again=pending;pending=false;if(!again)manual=false;}if(again)check(true);}}},"fragment-update").start();}
 public synchronized void later(){if(ready!=null)prefs.edit().putInt("deferredCode",ready.release.code).putLong("deferredUntil",System.currentTimeMillis()+86400000L).apply();}
 public synchronized void installerFinished(){installActive=false;}
 private PackageInfo installed()throws Exception{return context.getPackageManager().getPackageInfo(context.getPackageName(),Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);}
 private void active(long generation)throws Cancelled{synchronized(this){if(generation!=epoch)throw new Cancelled();}}
 private JSONObject readJson(String url,int limit,long generation)throws Exception{active(generation);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setUseCaches(false);try{if(c.getResponseCode()!=200)throw new IOException("GitHub недоступен. Повторная проверка — при возвращении в приложение.");InputStream in=c.getInputStream();try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){active(generation);if(out.size()+n>limit)throw new IOException("Некорректный размер списка обновлений");out.write(b,0,n);}return new JSONObject(new String(out.toByteArray(),"UTF-8"));}finally{in.close();}}finally{c.disconnect();}}
 private List<UpdatePolicy.Release> releases(JSONObject data)throws Exception{if(data.optInt("schema")!=1&&data.optInt("schema")!=2)throw new IOException("Неподдерживаемый список обновлений");JSONArray rows=data.getJSONArray("releases");if(rows.length()>100)throw new IOException("Слишком большой список обновлений");List<UpdatePolicy.Release> list=new ArrayList<UpdatePolicy.Release>();Set<Integer> codes=new HashSet<Integer>();for(int i=0;i<rows.length();i++){JSONObject v=rows.getJSONObject(i);UpdatePolicy.Release r=new UpdatePolicy.Release();r.version=v.getString("version");r.code=v.getInt("versionCode");r.channel=v.getString("channel");r.publishedAt=v.optString("publishedAt",v.getString("date")+"T00:00:00Z");r.packageName=v.optString("packageName","ru.fragment.logoeditor");r.minSdk=v.optInt("minSdk",23);r.abis=strings(v.optJSONArray("abis"));r.apk=v.getString("apk");r.verification=v.optString("verification","");if(!r.version.matches("[0-9]+\\.[0-9]+(\\.[0-9]+)?")||r.code<=0||!codes.add(r.code)||!Arrays.asList("stable","testing","experimental").contains(r.channel)||!r.publishedAt.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z"))throw new IOException("Некорректная запись обновления");if(!UpdatePolicy.trusted(r.apk,".apk"))throw new IOException("Некорректная ссылка APK");if(!r.verification.isEmpty()&&!UpdatePolicy.trusted(r.verification,".json"))throw new IOException("Некорректная ссылка проверки APK");list.add(r);}return list;}
 private static String[] strings(JSONArray a)throws Exception{if(a==null)return new String[]{"universal"};String[] out=new String[a.length()];for(int i=0;i<out.length;i++)out[i]=a.getString(i);return out;}
 private void perform(final long generation)throws Exception{synchronized(this){ready=null;}emit(generation,"checking","Проверяем последнюю опубликованную совместимую сборку…",null);JSONObject feed=readJson(FEED+"?check="+System.currentTimeMillis(),1048576,generation);List<UpdatePolicy.Release> all=releases(feed);boolean only=stableOnly();if(only&&!UpdatePolicy.hasStable(all)){emit(generation,"noStable","Стабильных сборок пока нет. Выключите «Только стабильные версии», чтобы получать тестовые и экспериментальные.",null);return;}final UpdatePolicy.Release selected=UpdatePolicy.choose(all,only,Build.VERSION.SDK_INT,Build.SUPPORTED_ABIS,context.getPackageName(),installed().versionCode);if(selected==null){emit(generation,"upToDate",only?"Новой совместимой стабильной сборки нет. Установленная версия не будет понижена.":"Новых совместимых сборок нет. Проверены стабильные, тестовые и экспериментальные.",null);return;}
  if(!UpdatePolicy.trusted(selected.verification,".json"))throw new IOException("У выбранной сборки нет данных проверки APK. Обновление не загружается.");
  final Spec spec=spec(selected,readJson(selected.verification+"?check="+System.currentTimeMillis(),65536,generation));active(generation);
  final boolean[] downloaded={false};File apk=UpdateCache.obtain(spec.file,new UpdateCache.Downloader(){public void download(File target)throws Exception{downloaded[0]=true;downloadApk(spec,target,generation);}},new UpdateCache.Verifier(){public void verify(File file)throws Exception{verifyApk(spec,file);}});active(generation);
  synchronized(this){if(generation!=epoch)throw new Cancelled();ready=spec;ready.file=apk;}emit(generation,"ready","APK "+selected.version+(downloaded[0]?" скачан и проверен. Установку подтверждает Android.":" уже скачан и проверен повторно без загрузки. Установку подтверждает Android."),selected);cleanup(apk);
 }
 private Spec spec(UpdatePolicy.Release r,JSONObject m)throws Exception{Spec s=new Spec();s.release=r;s.size=m.getLong("size");s.sha=m.getString("sha256").toLowerCase(Locale.US);s.signers=new HashSet<String>(Arrays.asList(strings(m.getJSONArray("signerSha256"))));if(m.optInt("schema")!=1||s.size<1||s.size>100*1024*1024L||!s.sha.matches("[a-f0-9]{64}")||!m.getString("packageName").equals(r.packageName)||m.getInt("versionCode")!=r.code||!m.getString("version").equals(r.version)||m.getInt("minSdk")!=r.minSdk||!new HashSet<String>(Arrays.asList(strings(m.getJSONArray("abis")))).equals(new HashSet<String>(Arrays.asList(r.abis))))throw new IOException("Данные проверки APK не совпадают со списком выпуска");if(s.signers.isEmpty())throw new IOException("Нет подписи выпуска");for(String cert:s.signers)if(!cert.matches("[a-f0-9]{64}"))throw new IOException("Некорректная подпись выпуска");s.file=new File(dir,r.code+"-"+s.sha+".apk");return s;}
 private Set<String> signatures(PackageInfo p)throws Exception{android.content.pm.Signature[] certs=Build.VERSION.SDK_INT>=28&&p.signingInfo!=null?p.signingInfo.getApkContentsSigners():p.signatures;Set<String> hashes=new HashSet<String>();if(certs!=null)for(android.content.pm.Signature cert:certs)hashes.add(UpdateCache.hex(MessageDigest.getInstance("SHA-256").digest(cert.toByteArray())));return hashes;}
 private void verifyApk(Spec s,File file)throws Exception{
  Set<String> verified=ApkIntegrity.verify(file,s.size,s.sha,s.signers,s.release.minSdk),own=signatures(installed());if(own.isEmpty()||!verified.equals(own))throw new IOException("APK подписан другим разработчиком");
  PackageInfo p=context.getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);if(p==null||!context.getPackageName().equals(p.packageName)||!s.release.packageName.equals(p.packageName))throw new IOException("Имя пакета APK не совпадает с приложением");if(!UpdatePolicy.identity(s.release,p.packageName,p.versionCode,p.versionName))throw new IOException("Номер версии внутри APK не совпадает с выпуском");if(!signatures(p).equals(own))throw new IOException("Android отклонил подпись APK");
  Set<String> actualAbis=new HashSet<String>();ZipFile zip=new ZipFile(file);try{Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){String n=entries.nextElement().getName();if(n.startsWith("lib/")&&n.endsWith(".so")){String[] pieces=n.split("/");if(pieces.length>=3)actualAbis.add(pieces[1]);}}}finally{zip.close();}if(actualAbis.isEmpty())actualAbis.add("universal");if(!actualAbis.equals(new HashSet<String>(Arrays.asList(s.release.abis))))throw new IOException("Архитектура APK не совпадает с выпуском");if(!UpdatePolicy.compatible(s.release,Build.VERSION.SDK_INT,Build.SUPPORTED_ABIS,context.getPackageName()))throw new IOException("APK несовместим с этим устройством");
 }
 private void downloadApk(Spec s,File target,long generation)throws Exception{active(generation);if(dir.getUsableSpace()<s.size+2*1024*1024L)throw new IOException("Недостаточно места для обновления");emit(generation,"downloading","Автоматически скачиваем APK "+s.release.version+"…",s.release);HttpURLConnection c=(HttpURLConnection)new URL(s.release.apk).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Не удалось скачать APK с GitHub");String header=c.getHeaderField("Content-Length");long length=header==null?-1:Long.parseLong(header);if(length!=-1&&length!=s.size)throw new IOException("Размер загрузки APK не совпадает с выпуском");InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(target);try{byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){active(generation);total+=n;if(total>s.size)throw new IOException("APK больше размера выпуска");out.write(buffer,0,n);}out.getFD().sync();}finally{try{in.close();}finally{out.close();}}}finally{c.disconnect();}}
 private void cleanup(File keep){try{int current=installed().versionCode;File[] files=dir.listFiles();if(files==null)return;for(File f:files){String n=f.getName();if(!f.equals(keep)&&n.matches("[0-9]+-[a-f0-9]{64}\\.apk")&&Long.parseLong(n.substring(0,n.indexOf('-')))<=current)f.delete();}}catch(Exception ignored){}}
 private synchronized void emit(long generation,String phase,String message,UpdatePolicy.Release r){if(generation!=epoch)return;try{boolean prompt=phase.equals("ready")&&r!=null&&UpdatePolicy.shouldPrompt(r.code,prefs.getInt("deferredCode",-1),prefs.getLong("deferredUntil",0),System.currentTimeMillis(),manual,installActive);state=new JSONObject().put("phase",phase).put("message",message).put("manual",manual).put("stableOnly",stableOnly()).put("prompt",prompt);if(r!=null)state.put("version",r.version).put("versionCode",r.code).put("channel",r.channel);host.state(new JSONObject(state.toString()));}catch(Exception ignored){}}
 public void install(){final Spec s;final long generation; synchronized(this){s=ready;generation=epoch;if(s==null)return;installActive=true;}new Thread(new Runnable(){public void run(){try{if(!UpdatePolicy.allowed(s.release,stableOnly())||s.release.code<=installed().versionCode)throw new IOException("Выбранная сборка больше не разрешена настройками");verifyApk(s,s.file);synchronized(UpdateManager.this){if(generation!=epoch)throw new IOException("Настройки разрешённых сборок изменились");}host.install(s.file);}catch(Exception e){synchronized(UpdateManager.this){installActive=false;}emit(epoch,"error",e.getMessage()==null?"Не удалось проверить APK перед установкой":e.getMessage(),null);}}},"fragment-install-verify").start();}
}
